<?php
function getCourse(int $id):array{$c=one('SELECT c.*,g.name category_name,u.name instructor_name FROM courses c JOIN categories g ON g.id=c.category_id JOIN users u ON u.id=c.instructor_id WHERE c.id=?',[$id]);if(!$c)reject('Không tìm thấy khóa học.',404);return $c;}
function ownerCourse(int $id):array{$u=requireUser('instructor');$c=getCourse($id);if((int)$c['instructor_id']!==(int)$u['id'])reject('Không tìm thấy khóa học.',404);return $c;}
function enrolled(int $courseId):array{$u=requireUser('student');$e=one('SELECT * FROM enrollments WHERE user_id=? AND course_id=?',[$u['id'],$courseId]);if(!$e)reject('Bạn cần tham gia khóa học trước.',403);return $e;}
function courseLessons(int $id):array{return all('SELECT l.*,ch.course_id,ch.title chapter_title,ch.position chapter_position FROM lessons l JOIN chapters ch ON ch.id=l.chapter_id WHERE ch.course_id=? ORDER BY ch.position,ch.id,l.position,l.id',[$id]);}
function hasEnrollment(int $id):bool{return (int)val('SELECT COUNT(*) FROM enrollments WHERE course_id=?',[$id])>0;}
function structureOpen(array $c):void{if($c['status']!=='draft'||hasEnrollment((int)$c['id']))reject('Cấu trúc chỉ sửa khi bản nháp chưa có enrollment.',409);}
function lessonCourse(int $id):array{$l=one('SELECT l.*,ch.course_id FROM lessons l JOIN chapters ch ON ch.id=l.chapter_id WHERE l.id=?',[$id]);if(!$l)reject('Không tìm thấy bài học.',404);return $l;}
function progressFor(int $user,int $course):array{$total=(int)val('SELECT COUNT(*) FROM lessons l JOIN chapters c ON c.id=l.chapter_id WHERE c.course_id=?',[$course]);$done=(int)val('SELECT COUNT(*) FROM lesson_progress p JOIN lessons l ON l.id=p.lesson_id JOIN chapters c ON c.id=l.chapter_id WHERE p.user_id=? AND c.course_id=?',[$user,$course]);$best=val('SELECT MAX(a.score_percent) FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.user_id=? AND q.course_id=?',[$user,$course]);return ['total'=>$total,'done'=>$done,'percent'=>$total?round($done/$total*100,2):0,'best'=>$best===null?null:(float)$best];}
function completionService(int $user,int $course):void{global $config;$e=one('SELECT * FROM enrollments WHERE user_id=? AND course_id=?'.($config['db_driver']==='mysql'?' FOR UPDATE':''),[$user,$course]);if(!$e||$e['completed_at'])return;$p=progressFor($user,$course);if($p['total']>0&&$p['done']===$p['total']&&(int)val('SELECT COUNT(*) FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.user_id=? AND q.course_id=? AND a.passed=1',[$user,$course])>0)run('UPDATE enrollments SET completed_at=?,updated_at=? WHERE id=? AND completed_at IS NULL',[now(),now(),$e['id']]);}
function questionsFor(int $course):array{$quiz=one('SELECT * FROM quizzes WHERE course_id=?',[$course]);if(!$quiz)return [];$qs=all('SELECT * FROM questions WHERE quiz_id=? ORDER BY position,id',[$quiz['id']]);foreach($qs as &$q)$q['answers']=all('SELECT * FROM answers WHERE question_id=? ORDER BY position,id',[$q['id']]);return $qs;}
function readyForQuiz(int $course):array{$e=enrolled($course);$p=progressFor((int)$e['user_id'],$course);if(!$p['total']||$p['done']!==$p['total'])reject('Hoàn thành tất cả bài học để mở quiz.',403);return $e;}
function passwordInput():string{$p=(string)($_POST['password']??'');if(length($p)<10||strlen($p)>72)reject('Mật khẩu tối thiểu 10 ký tự và tối đa 72 byte UTF-8.');if($p!==($_POST['password_confirmation']??''))reject('Mật khẩu xác nhận không khớp.');return $p;}
function coverKey():string{$k=(string)($_POST['cover_key']??'default');if(!in_array($k,['default','web','programming','database'],true))reject('Ảnh bìa không hợp lệ.');return $k;}
function minuteLimit(string $prefix,int $max):void{$bucket=intdiv(time(),60);if(!takeQuota([$prefix.':'.$bucket=>['max'=>$max,'until'=>($bucket+1)*60]]))reject('Quá số lần thử. Vui lòng thử lại sau một phút.',429);}
function uuid():string{$data=random_bytes(16);$data[6]=chr((ord($data[6])&0x0f)|0x40);$data[8]=chr((ord($data[8])&0x3f)|0x80);$hex=bin2hex($data);return substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);}
function storeAttempt(int $courseId,int $userId,string $requestId,array $selected):int{
 if(!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i',$requestId))reject('request_id không hợp lệ.');
 return transaction(function()use($courseId,$userId,$requestId,$selected){lockCourse($courseId);$quiz=one('SELECT * FROM quizzes WHERE course_id=?',[$courseId]);if(!$quiz)reject('Chưa có quiz.',404);$qs=questionsFor($courseId);$normal=[];foreach($selected as $qid=>$aid){if(!is_scalar($aid)||!preg_match('/^[0-9]+$/',(string)$aid))reject('Đáp án không hợp lệ.');$q=array_values(array_filter($qs,fn($q)=>(int)$q['id']===(int)$qid))[0]??null;if(!$q||!in_array((int)$aid,array_map(fn($a)=>(int)$a['id'],$q['answers']),true))reject('Đáp án không thuộc đúng câu/quiz.');}
 foreach($qs as $q)$normal[(int)$q['id']]=isset($selected[$q['id']])?(int)$selected[$q['id']]:null;ksort($normal);$hash=hash('sha256',json_encode(['quiz_id'=>(int)$quiz['id'],'answers'=>$normal]));$old=one('SELECT * FROM quiz_attempts WHERE user_id=? AND request_id=?',[$userId,$requestId]);if($old){if(!hash_equals($old['submission_hash'],$hash))reject('UUID đã được dùng với nội dung khác.',409);return (int)$old['id'];}
 $p=progressFor($userId,$courseId);if(!$p['total']||$p['done']!==$p['total'])reject('Chưa hoàn thành toàn bộ bài học.',403);if(count($qs)<5)reject('Quiz chưa hợp lệ.',409);$right=0;foreach($qs as $q){$correct=(int)array_values(array_filter($q['answers'],fn($a)=>(int)$a['is_correct']===1))[0]['id'];if($normal[$q['id']]===$correct)$right++;}$stamp=['created_at'=>now(),'updated_at'=>now()];$score=round($right/count($qs)*100,2);$passed=$right/count($qs)>=.7;
 $attempt=insertRow('quiz_attempts',['user_id'=>$userId,'quiz_id'=>$quiz['id'],'request_id'=>$requestId,'submission_hash'=>$hash,'correct_count'=>$right,'total_questions'=>count($qs),'score_percent'=>$score,'passed'=>(int)$passed,'submitted_at'=>now()]+$stamp);
 foreach($qs as $q){$correct=(int)array_values(array_filter($q['answers'],fn($a)=>(int)$a['is_correct']===1))[0]['id'];insertRow('quiz_answers',['attempt_id'=>$attempt,'question_id'=>$q['id'],'answer_id'=>$normal[$q['id']],'is_correct'=>(int)($normal[$q['id']]===$correct)]+$stamp);}completionService($userId,$courseId);return $attempt;
 });
}
